const BASE_URL = 'https://api.hubapi.com';
const token = $env.HUBSPOT_ACCESS_TOKEN;

if (!token) {
  throw new Error('Falta HUBSPOT_ACCESS_TOKEN en variables de entorno de n8n');
}

const query = $('Webhook').first().json.query || {};
const periodo = query.periodo || 'mensual';
const staticData = $getWorkflowStaticData('global');
const cacheKey = `dashboard:${periodo}`;
const cacheTtlMs = Number(query.cacheTtlMs || 120000);
const cached = staticData[cacheKey];

if (query.force !== 'true' && cached?.payload && !staticData.cacheDirty && Date.now() - cached.savedAt < cacheTtlMs) {
  return [{
    json: {
      ...cached.payload,
      cache: {
        hit: true,
        savedAt: cached.savedAt,
        ageMs: Date.now() - cached.savedAt,
        dirty: Boolean(staticData.cacheDirty)
      }
    }
  }];
}

function getPeriodRange(value) {
  const now = new Date();
  const end = new Date(now);
  end.setHours(23, 59, 59, 999);

  const start = new Date(now);
  start.setHours(0, 0, 0, 0);

  if (value === 'diario') return { start, end };

  if (value === 'trimestral') {
    const quarterStartMonth = Math.floor(now.getMonth() / 3) * 3;
    start.setMonth(quarterStartMonth, 1);
    return { start, end };
  }

  start.setDate(1);
  return { start, end };
}

const { start, end } = getPeriodRange(periodo);

const n8nContext = this;

async function hubspotFetch(path, options = {}) {
  const requestOptions = {
    method: options.method || 'GET',
    url: `${BASE_URL}${path}`,
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
      ...(options.headers || {})
    },
    json: true
  };

  if (options.body) {
    requestOptions.body = typeof options.body === 'string'
      ? JSON.parse(options.body)
      : options.body;
  }

  return await n8nContext.helpers.httpRequest(requestOptions);
}

function chunkArray(arr, size = 100) {
  const chunks = [];
  for (let i = 0; i < arr.length; i += size) chunks.push(arr.slice(i, i + size));
  return chunks;
}

async function searchDeals() {
  const deals = [];
  let after = null;

  do {
    const body = {
      filterGroups: [
        {
          filters: [
            { propertyName: 'closedate', operator: 'GTE', value: String(start.getTime()) },
            { propertyName: 'closedate', operator: 'LTE', value: String(end.getTime()) }
          ]
        }
      ],
      properties: [
        'dealname',
        'amount',
        'dealstage',
        'pipeline',
        'closedate',
        'createdate',
        'hs_lastmodifieddate',
        'hubspot_owner_id'
      ],
      limit: 100,
      sorts: [{ propertyName: 'closedate', direction: 'DESCENDING' }]
    };

    if (after) body.after = after;

    const data = await hubspotFetch('/crm/v3/objects/deals/search', {
      method: 'POST',
      body: JSON.stringify(body)
    });

    deals.push(...(data.results || []));
    after = data.paging?.next?.after || null;
  } while (after);

  return deals;
}

async function getStageLabels() {
  const map = new Map();
  const data = await hubspotFetch('/crm/v3/pipelines/deals');

  for (const pipeline of data.results || []) {
    for (const stage of pipeline.stages || []) {
      if (stage.id) map.set(String(stage.id), stage.label || stage.id);
    }
  }

  return map;
}
async function getOwners() {
  const owners = [];
  const archivedModes = [false, true];

  for (const archived of archivedModes) {
    let after = null;

    do {
      const path = `/crm/v3/owners/?limit=100&archived=${archived}${after ? `&after=${after}` : ''}`;
      const data = await hubspotFetch(path);
      owners.push(...(data.results || []));
      after = data.paging?.next?.after || null;
    } while (after);
  }

  const map = new Map();
  for (const owner of owners) {
    if (owner.id) map.set(String(owner.id), owner);
    if (owner.userId) map.set(String(owner.userId), owner);
  }
  return map;
}

async function batchReadAssociations(fromObjectType, toObjectType, fromIds) {
  const map = new Map();
  const uniqueIds = [...new Set(fromIds.map(String))];

  for (const chunk of chunkArray(uniqueIds, 100)) {
    const data = await hubspotFetch(`/crm/v4/associations/${fromObjectType}/${toObjectType}/batch/read`, {
      method: 'POST',
      body: JSON.stringify({ inputs: chunk.map(id => ({ id })) })
    });

    for (const result of data.results || []) {
      const fromId = String(result.from?.id || result._from?.id || result.id || '');
      const toIds = (result.to || [])
        .map(item => String(item.toObjectId || item.id || ''))
        .filter(Boolean);
      if (fromId) map.set(fromId, toIds);
    }
  }

  return map;
}

async function batchReadObjects(objectType, ids, properties) {
  const map = new Map();
  const uniqueIds = [...new Set(ids.map(String))].filter(Boolean);
  if (!uniqueIds.length) return map;

  for (const chunk of chunkArray(uniqueIds, 100)) {
    const data = await hubspotFetch(`/crm/v3/objects/${objectType}/batch/read`, {
      method: 'POST',
      body: JSON.stringify({ properties, inputs: chunk.map(id => ({ id })) })
    });

    for (const item of data.results || []) map.set(String(item.id), item);
  }

  return map;
}

const startedAt = Date.now();
const deals = await searchDeals();
const dealIds = deals.map(deal => String(deal.id));

const [ownerMap, stageLabelMap, contactAssociations, lineItemAssociations] = await Promise.all([
  getOwners(),
  getStageLabels(),
  batchReadAssociations('deals', 'contacts', dealIds),
  batchReadAssociations('deals', 'line_items', dealIds)
]);

const contactIds = [...contactAssociations.values()].flat();
const lineItemIds = [...lineItemAssociations.values()].flat();

const [contactMap, lineItemMap] = await Promise.all([
  batchReadObjects('contacts', contactIds, ['firstname', 'lastname', 'email', 'phone', 'company']),
  batchReadObjects('line_items', lineItemIds, ['name', 'quantity', 'price', 'amount', 'hs_product_id', 'hs_sku'])
]);

const result = deals.map(deal => {
  const props = deal.properties || {};
  const ownerId = props.hubspot_owner_id ? String(props.hubspot_owner_id) : null;
  const owner = ownerId ? ownerMap.get(ownerId) || null : null;

  const contacts = (contactAssociations.get(String(deal.id)) || [])
    .map(id => contactMap.get(String(id)))
    .filter(Boolean)
    .map(contact => ({
      id: contact.id,
      firstname: contact.properties?.firstname || null,
      lastname: contact.properties?.lastname || null,
      email: contact.properties?.email || null,
      phone: contact.properties?.phone || null,
      company: contact.properties?.company || null
    }));

  const lineItems = (lineItemAssociations.get(String(deal.id)) || [])
    .map(id => lineItemMap.get(String(id)))
    .filter(Boolean)
    .map(item => ({
      id: item.id,
      name: item.properties?.name || null,
      quantity: item.properties?.quantity || null,
      price: item.properties?.price || null,
      amount: item.properties?.amount || null,
      hs_product_id: item.properties?.hs_product_id || null,
      sku: item.properties?.hs_sku || null
    }));

  return {
    dealId: deal.id,
    dealName: props.dealname || null,
    amount: props.amount || null,
    dealStage: props.dealstage || null,
    dealStageLabel: props.dealstage ? stageLabelMap.get(String(props.dealstage)) || null : null,
    pipeline: props.pipeline || null,
    closeDate: props.closedate || null,
    createDate: props.createdate || null,
    lastModifiedDate: props.hs_lastmodifieddate || null,
    hubspotOwnerId: ownerId,
    owner: owner
      ? {
          id: owner.id || null,
          userId: owner.userId || null,
          firstName: owner.firstName || null,
          lastName: owner.lastName || null,
          email: owner.email || null
        }
      : null,
    contacts,
    lineItems
  };
});

const payload = {
  periodo,
  desdeISO: start.toISOString(),
  hastaISO: end.toISOString(),
  totalDeals: result.length,
  totalLineItems: lineItemIds.length,
  elapsedMs: Date.now() - startedAt,
  deals: result
};

staticData[cacheKey] = {
  savedAt: Date.now(),
  payload
};
staticData.cacheDirty = false;
staticData.lastBuild = {
  at: new Date().toISOString(),
  periodo,
  totalDeals: result.length,
  totalLineItems: lineItemIds.length
};

return [{
  json: {
    ...payload,
    cache: {
      hit: false,
      savedAt: staticData[cacheKey].savedAt,
      ageMs: 0,
      dirty: false
    }
  }
}];

const staticData = $getWorkflowStaticData('global');
const request = $('Webhook HubSpot Change').first().json;

staticData.cacheDirty = true;
staticData.lastInvalidation = {
  at: new Date().toISOString(),
  source: 'hubspot-workflow',
  body: request.body || request,
  query: request.query || {}
};

return [{
  json: {
    ok: true,
    cacheDirty: true,
    receivedAt: staticData.lastInvalidation.at,
    message: 'Dashboard cache invalidated. Next dashboard request will rebuild data.',
    received: staticData.lastInvalidation.body
  }
}];
